-- 2026-08-01: original Ziman editorial wave.
BEGIN;
SET LOCAL ROLE postgres;
CREATE TEMP TABLE _ziman_wave_source (source_id text primary key, category_name text not null, language_code text not null, prompt text not null, option_a text not null, option_b text not null, option_c text not null, option_d text not null, correct_option text not null, explanation text not null, difficulty integer not null, source_url text not null) ON COMMIT DROP;
CREATE TEMP TABLE _ziman_wave_inserted (question_id uuid) ON COMMIT DROP;
WITH inserted AS (
  SELECT c.id,s.language_code,s.prompt,s.option_a,s.option_b,s.option_c,s.option_d,s.correct_option,s.explanation,s.difficulty,true,'multiple_choice',NULL,s.source_url,'approved','Kurmancî','Ziman editorial wave — 2026-08-01',s.source_url,1,now()
  FROM _ziman_wave_source s JOIN public.categories c ON c.name=s.category_name
  WHERE NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.language_code=s.language_code AND lower(trim(q.prompt))=lower(trim(s.prompt)))
  RETURNING id
) INSERT INTO _ziman_wave_inserted SELECT id FROM inserted;
DO $$ DECLARE source_count integer; inserted_count integer; missing_categories integer; BEGIN SELECT count(*) INTO source_count FROM _ziman_wave_source; SELECT count(*) INTO inserted_count FROM _ziman_wave_inserted; SELECT count(*) INTO missing_categories FROM _ziman_wave_source s LEFT JOIN public.categories c ON c.name=s.category_name WHERE c.id IS NULL; IF source_count<>95 OR inserted_count<>95 OR missing_categories<>0 THEN RAISE EXCEPTION 'Ziman wave guard failed: source=%, inserted=%, missing_categories=%',source_count,inserted_count,missing_categories; END IF; END $$;
COMMIT;
